// Turn n8n's error payload into one readable log row.
const e = $input.first().json;
const ex = e.execution || {};
const err = ex.error || {};
return [{ json: {
  occurredAt: new Date().toISOString(),
  workflowName: (e.workflow && e.workflow.name) || '',
  executionId: String(ex.id || ''),
  executionUrl: ex.url || '',
  failedNode: ex.lastNodeExecuted || (err.node && err.node.name) || '',
  errorMessage: String(err.message || err.description || 'Unknown error').slice(0, 1000),
  mode: ex.mode || ''
} }];
